document.querySelectorAll('.fn-share').forEach(button=>{button.addEventListener('click',async()=>{const url=location.origin+location.pathname;const data={title:document.title,url};if(navigator.share){try{await navigator.share(data);return}catch(error){if(error.name==='AbortError')return}}try{await navigator.clipboard.writeText(url);button.textContent='Link copied ✓';setTimeout(()=>button.textContent='Share itinerary ↗',2500)}catch{const field=document.createElement('input');field.value=url;field.readOnly=true;field.setAttribute('aria-label','Itinerary link to copy');button.after(field);field.focus();field.select();button.textContent='Copy the link below'}})});